import numpy as np
import pandas as pd
import pytz

def r_as_POSIXct(x, tz="", *args, **kwargs):
    """
    Python implementation of R's as.POSIXct.

    R's POSIXct uses the origin 1970-01-01 UTC for its underlying numeric value,
    but accepts an 'origin' parameter when converting numeric values (defaults to 1970-01-01).
    """
    # Handle the 'origin' parameter from ... (kwargs)
    origin_str = kwargs.get('origin', '1970-01-01')
    # R origin "1960-01-01" is common. Pandas handles this via the origin parameter.

    # If x is already a pandas Timestamp or DatetimeIndex
    if isinstance(x, (pd.Timestamp, pd.DatetimeIndex)):
        if tz == "":
            return x
        if isinstance(x, pd.Timestamp):
            return x.tz_localize(tz).tz_convert(tz) if x.tzinfo is None else x.tz_convert(tz)
        else:
            return x.tz_localize(tz).tz_convert(tz) if x.tzinfo is None else x.tz_convert(tz)

    # Handle NULL (None)
    if x is None:
        return np.array([], dtype='datetime64[s]')

    # Handle character or factor
    if isinstance(x, (str, list)) or (isinstance(x, np.ndarray) and x.dtype == object):
        # R's as.POSIXct(as.POSIXlt(x, tz, ...), tz, ...)
        # We use pandas to_datetime which is very flexible.
        ts = pd.to_datetime(x, errors='coerce')

        # Determine timezone
        target_tz = pytz.timezone(tz) if tz != "" else pytz.UTC

        if isinstance(ts, pd.Timestamp):
            if ts.tzinfo is None:
                return ts.tz_localize(target_tz)
            return ts.tz_convert(target_tz)
        else: # DatetimeIndex
            if ts.tzinfo is None:
                return ts.tz_localize(target_tz)
            return ts.tz_convert(target_tz)

    # Handle numeric (integers/floats)
    # R treats numeric as seconds since 'origin'
    if isinstance(x, (int, float, np.integer, np.floating)) or (isinstance(x, np.ndarray) and np.issubdtype(x.dtype, np.number)):
        # Convert origin string to a Timestamp
        origin_ts = pd.Timestamp(origin_str, tz='UTC')

        if isinstance(x, (int, float, np.integer, np.floating)):
            # result = origin + x seconds
            res = origin_ts + pd.to_timedelta(x, unit='s')
            target_tz = pytz.timezone(tz) if tz != "" else pytz.UTC
            return res.tz_convert(target_tz)
        else:
            # Vector of numbers
            # We create a series of timedeltas and add to the origin
            deltas = pd.to_timedelta(x, unit='s')
            res = origin_ts + deltas
            target_tz = pytz.timezone(tz) if tz != "" else pytz.UTC
            return res.tz_convert(target_tz)

    # Handle logical vector where all are NA
    if isinstance(x, np.ndarray) and x.dtype == bool:
        if np.all(pd.isna(x)):
            return np.array([pd.NaT], dtype='datetime64[s]')

    # If x is float (but not in a numpy array), check if it's actually a numeric date
    if isinstance(x, float):
        return r_as_POSIXct(np.array([x]), tz=tz, *args, **kwargs)[0]

    # Final fallback for unexpected types (trying to treat as numeric if possible)
    try:
        num_x = np.asanyarray(x, dtype=float)
        return r_as_POSIXct(num_x, tz=tz, *args, **kwargs)
    except:
        raise TypeError(f"do not know how to convert {type(x)} to class POSIXct")
